"""
End-to-end mission simulation and geospatial schema verification tests.
Meticulously tests CZML, GeoJSON, and TLE ingestion integrity.
"""

import json
import unittest


class TestMissionGeospatialFormats(unittest.TestCase):
    """Verifies that NADIR geospatial outputs adhere to standard schemas."""

    def test_geojson_feature_collection_schema(self):
        """Verifies that sample GeoJSON generated by NADIR is valid JSON with valid features."""
        sample_geojson = """{
  "type": "FeatureCollection",
  "features": [
    {
      "type": "Feature",
      "properties": {
        "target_id": "T01",
        "name": "Suez Canal Maritime Chokepoint",
        "priority": 0,
        "min_elevation_deg": 20.00,
        "max_off_nadir_deg": 30.00
      },
      "geometry": {
        "type": "Point",
        "coordinates": [32.265400, 30.585200, 10.0]
      }
    }
  ]
}"""
        data = json.loads(sample_geojson)
        self.assertEqual(data["type"], "FeatureCollection")
        self.assertEqual(len(data["features"]), 1)
        feat = data["features"][0]
        self.assertEqual(feat["type"], "Feature")
        self.assertEqual(feat["geometry"]["type"], "Point")
        self.assertEqual(feat["geometry"]["coordinates"], [32.2654, 30.5852, 10.0])
        self.assertEqual(feat["properties"]["target_id"], "T01")

    def test_czml_packet_schema(self):
        """Verifies that CZML generated by NADIR adheres to Cesium specifications."""
        sample_czml = """[
  {
    "id": "document",
    "name": "NADIR Constellation Simulation",
    "version": "1.0",
    "clock": {
      "interval": "2026-06-21T12:00:00Z/2026-06-21T14:00:00Z",
      "currentTime": "2026-06-21T12:00:00Z",
      "multiplier": 60,
      "range": "LOOP_STOP",
      "step": "SYSTEM_CLOCK_MULTIPLIER"
    }
  },
  {
    "id": "SAT_P00_S00",
    "name": "SAT_P00_S00",
    "position": {
      "interpolationAlgorithm": "LAGRANGE",
      "interpolationDegree": 5,
      "referenceFrame": "FIXED",
      "epoch": "2026-06-21T12:00:00Z",
      "cartesian": [
        0.0, 4500000.0, 2000000.0, 5000000.0,
        60.0, 4450000.0, 2100000.0, 5050000.0
      ]
    },
    "point": {
      "color": { "rgba": [0, 220, 255, 255] },
      "pixelSize": 7
    }
  }
]"""
        doc = json.loads(sample_czml)
        self.assertIsInstance(doc, list)
        self.assertEqual(len(doc), 2)
        doc_header = doc[0]
        self.assertEqual(doc_header["id"], "document")
        self.assertEqual(doc_header["version"], "1.0")
        sat_packet = doc[1]
        self.assertEqual(sat_packet["id"], "SAT_P00_S00")
        self.assertEqual(sat_packet["position"]["interpolationAlgorithm"], "LAGRANGE")
        self.assertEqual(len(sat_packet["position"]["cartesian"]), 8)

    def test_tle_checksum_modulo(self):
        """Verifies that standard NORAD TLE checksum modulo algorithm executes accurately."""
        line1 = "1 25544U 98067A   26050.50000000  .00016717  00000-0  10270-3 0  9005"
        # In TLE, each digit adds its value, minus adds 1, all others 0, modulo 10
        total = 0
        for char in line1[:-1]:
            if char.isdigit():
                total += int(char)
            elif char == "-":
                total += 1
        expected_check = total % 10
        self.assertEqual(expected_check, int(line1[-1]))


if __name__ == "__main__":
    unittest.main()
